components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: 0.375rem; box-sizing: border-box; height: 2.25rem; padding: 0 0.625rem; border: 1px solid transparent; border-radius: var(--radius, 0.5rem); background-clip: padding-box; font: 500 0.875rem/1.25rem "Inter Variable", system-ui, sans-serif; white-space: nowrap; cursor: pointer; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); background: var(--primary, light-dark(#126e79, #38c2cf)); color: var(--primary-foreground, light-dark(#fff, #092125)); }
.ds-button-primary:hover { background: color-mix(in oklab, var(--primary, light-dark(#126e79, #38c2cf)) 80%, transparent); }
.ds-button-primary:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; border-color: var(--ring, light-dark(#167d8b, #38c2cf)); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, light-dark(#167d8b, #38c2cf)) 50%, transparent); }
.ds-button-primary:active { translate: 0 1px; }
.ds-button-primary:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-primary { transition-duration: 0.01ms; } }

.ds-button-outline { display: inline-flex; align-items: center; justify-content: center; gap: 0.375rem; box-sizing: border-box; min-height: 36px; padding: 0 0.625rem; border: 1px solid transparent; border-radius: var(--radius, 0.5rem); background-clip: padding-box; font: 500 0.875rem/1.25rem "Inter Variable", system-ui, sans-serif; white-space: nowrap; cursor: pointer; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); background: light-dark(var(--background, light-dark(#fff, #15181b)), color-mix(in oklab, var(--input, light-dark(#b0bec2, #55666b)) 30%, transparent)); color: var(--foreground, light-dark(#20282b, #e9edef)); border-color: light-dark(var(--border, light-dark(#dce4e6, #30383d)), var(--input, light-dark(#b0bec2, #55666b))); }
.ds-button-outline:hover { background: light-dark(var(--muted, light-dark(#edf1f2, #242a2e)), color-mix(in oklab, var(--input, light-dark(#b0bec2, #55666b)) 50%, transparent)); color: var(--foreground, light-dark(#20282b, #e9edef)); }
.ds-button-outline:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; border-color: var(--ring, light-dark(#167d8b, #38c2cf)); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, light-dark(#167d8b, #38c2cf)) 50%, transparent); }
.ds-button-outline:active { translate: 0 1px; }
.ds-button-outline:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-outline { transition-duration: 0.01ms; } }

.ds-button-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 0.375rem; box-sizing: border-box; height: 2rem; width: 100%; justify-content: flex-start; padding: 0 0.625rem; border: 1px solid transparent; border-radius: var(--radius, 0.5rem); background-clip: padding-box; font: 500 0.875rem/1.25rem "Inter Variable", system-ui, sans-serif; white-space: nowrap; cursor: pointer; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); background: var(--secondary, light-dark(#e0f1f2, #183a3f)); color: var(--secondary-foreground, light-dark(#155963, #91e3e9)); }
.ds-button-secondary:hover { background: color-mix(in oklch, var(--secondary, light-dark(#e0f1f2, #183a3f)), var(--foreground, light-dark(#20282b, #e9edef)) 5%); }
.ds-button-secondary:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; border-color: var(--ring, light-dark(#167d8b, #38c2cf)); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, light-dark(#167d8b, #38c2cf)) 50%, transparent); }
.ds-button-secondary:active { translate: 0 1px; }
.ds-button-secondary:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-secondary { transition-duration: 0.01ms; } }

.ds-button-ghost { display: inline-flex; align-items: center; justify-content: center; gap: 0.375rem; box-sizing: border-box; width: 1.75rem; height: 1.75rem; padding: 0; border: 1px solid transparent; border-radius: var(--radius, 0.5rem); background-clip: padding-box; font: 500 0.875rem/1.25rem "Inter Variable", system-ui, sans-serif; white-space: nowrap; cursor: pointer; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); background: transparent; color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); }
.ds-button-ghost:hover { background: light-dark(var(--muted, light-dark(#edf1f2, #242a2e)), color-mix(in oklab, var(--muted, light-dark(#edf1f2, #242a2e)) 50%, transparent)); color: var(--foreground, light-dark(#20282b, #e9edef)); }
.ds-button-ghost:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; border-color: var(--ring, light-dark(#167d8b, #38c2cf)); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, light-dark(#167d8b, #38c2cf)) 50%, transparent); }
.ds-button-ghost:active { translate: 0 1px; }
.ds-button-ghost:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-ghost { transition-duration: 0.01ms; } }

.ds-search { display: flex; gap: 8px; align-items: center; min-width: min(210px, 100%); box-sizing: border-box; min-height: 36px; padding: 0 9px; border: 1px solid var(--border, light-dark(#dce4e6, #30383d)); border-radius: var(--radius, 0.5rem); background: var(--background, light-dark(#fff, #15181b)); color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); }
.ds-search svg { flex: none; }
.ds-search-field { width: 100%; min-width: 0; height: 2rem; padding: 0.25rem 0; box-sizing: border-box; border: 0; background: transparent; outline: none; color: var(--foreground, light-dark(#20282b, #e9edef)); font: 400 1rem/1.5 "Inter Variable", system-ui, sans-serif; }
.ds-search-field::placeholder { color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); }
.ds-search:focus-within { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 1px; }
@media (min-width: 48rem) { .ds-search-field { font-size: 0.875rem; line-height: 1.25rem; } }

.ds-switches { display: flex; flex-wrap: wrap; gap: 10px 17px; }
.ds-switch-label { display: inline-flex; gap: 9px; align-items: center; min-height: 36px; cursor: pointer; font: 400 0.82rem/1.5 "Inter Variable", system-ui, sans-serif; color: var(--foreground, light-dark(#20282b, #e9edef)); }
.ds-switch { display: inline-flex; position: relative; flex: none; align-items: center; box-sizing: border-box; padding: 0; width: 32px; height: 18.4px; border: 1px solid transparent; border-radius: 9999px; background: light-dark(var(--input, light-dark(#b0bec2, #55666b)), color-mix(in oklab, var(--input, light-dark(#b0bec2, #55666b)) 80%, transparent)); cursor: pointer; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-switch::after { content: ''; position: absolute; inset: -0.5rem -0.75rem; }
.ds-switch-thumb { display: block; width: 1rem; height: 1rem; border-radius: 9999px; background: light-dark(var(--background, light-dark(#fff, #15181b)), var(--foreground, light-dark(#20282b, #e9edef))); pointer-events: none; transition: translate 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-switch[aria-checked='true'] { background: var(--primary, light-dark(#126e79, #38c2cf)); }
.ds-switch[aria-checked='true'] .ds-switch-thumb { translate: calc(100% - 2px) 0; background: light-dark(var(--background, light-dark(#fff, #15181b)), var(--primary-foreground, light-dark(#fff, #092125))); }
.ds-switch:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; border-color: var(--ring, light-dark(#167d8b, #38c2cf)); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, light-dark(#167d8b, #38c2cf)) 50%, transparent); }
.ds-switch:disabled { cursor: not-allowed; opacity: 0.5; }
@media (prefers-reduced-motion: reduce) { .ds-switch, .ds-switch-thumb { transition-duration: 0.01ms; } }

.ds-history { display: grid; gap: 4px; padding: 12px; background: var(--canvas, light-dark(#f4f5f7, #111316)); }
.ds-session { display: grid; gap: 4px; min-width: 0; padding: 10px 12px; border-radius: var(--radius, 0.5rem); font: 400 1rem/1.4 "Inter Variable", system-ui, sans-serif; color: var(--foreground, light-dark(#20282b, #e9edef)); text-decoration: none; }
.ds-session:not([aria-current]):hover { background: var(--muted, light-dark(#edf1f2, #242a2e)); }
.ds-session[aria-current='page'] { background: var(--secondary, light-dark(#e0f1f2, #183a3f)); color: var(--secondary-foreground, light-dark(#155963, #91e3e9)); }
.ds-session-date { font-size: 0.875rem; font-weight: 600; }
.ds-session-detail { display: flex; gap: 8px; flex-wrap: wrap; font-size: 0.75rem; color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); }
.ds-session-detail time { font-variant-numeric: tabular-nums; }
.ds-session:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; }

.ds-segment { display: grid; grid-template-columns: 64px minmax(0, 1fr) auto; gap: 12px; align-items: start; padding-block: 19px; border-bottom: 1px solid var(--border, light-dark(#dce4e6, #30383d)); color: var(--foreground, light-dark(#20282b, #e9edef)); }
.ds-timestamp { padding-top: 7px; color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); font: 400 0.8rem/1.5 "Inter Variable", system-ui, sans-serif; font-variant-numeric: tabular-nums; }
.ds-segment-text { min-width: 0; }
.ds-source, .ds-translation { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; user-select: text; }
.ds-source { font: 400 clamp(1.2rem, 2vw, 1.4rem)/1.48 "PT Serif", Georgia, serif; }
.ds-translation { margin-top: 6px; color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); font: 400 0.925rem/1.62 "Inter Variable", system-ui, sans-serif; }
.ds-copy-line { display: inline-grid; place-items: center; box-sizing: border-box; width: 1.75rem; height: 1.75rem; padding: 0; border: 1px solid transparent; border-radius: var(--radius, 0.5rem); background: transparent; color: var(--muted-foreground, light-dark(#53636a, #a8b5ba)); cursor: pointer; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-copy-line:hover { background: light-dark(var(--muted, light-dark(#edf1f2, #242a2e)), color-mix(in oklab, var(--muted, light-dark(#edf1f2, #242a2e)) 50%, transparent)); color: var(--foreground, light-dark(#20282b, #e9edef)); }
.ds-copy-line:focus-visible { outline: 2px solid var(--ring, light-dark(#167d8b, #38c2cf)); outline-offset: 3px; border-color: var(--ring, light-dark(#167d8b, #38c2cf)); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, light-dark(#167d8b, #38c2cf)) 50%, transparent); }
.ds-copy-line:active { translate: 0 1px; }
@media (max-width: 480px) { .ds-segment { grid-template-columns: minmax(0, 1fr) auto; gap: 4px 8px; padding-block: 13px; } .ds-timestamp { grid-column: 1; padding: 0; } .ds-segment-text { grid-row: 2; grid-column: 1 / -1; } .ds-copy-line { grid-row: 1; grid-column: 2; margin-block: -4px; } }
@media (prefers-reduced-motion: reduce) { .ds-copy-line { transition-duration: 0.01ms; } }
